const r = await tools.exec_command({"cmd":"cd /workspace && /opt/conda/bin/pvpython - <<'PY'
import vtk, numpy as np
from vtk.util.numpy_support import vtk_to_numpy
r=vtk.vtkXMLImageDataReader();r.SetFileName('Ocean.vti');r.Update();pd=r.GetOutput().GetPointData()
a,b,c,d=[vtk_to_numpy(pd.GetArray(k)).reshape(101,101) for k in 'ABCD']
p=a-d;q=b+c
for diag in [0,1]:
 roots=[]
 for j in range(100):
  for i in range(100):
   pts=[(i,j,p[j,i],q[j,i]),(i+1,j,p[j,i+1],q[j,i+1]),(i+1,j+1,p[j+1,i+1],q[j+1,i+1]),(i,j+1,p[j+1,i],q[j+1,i])]
   tris=[(0,1,2),(0,2,3)] if diag==0 else [(0,1,3),(1,2,3)]
   for tri in tris:
    M=np.array([[pts[t][2] for t in tri],[pts[t][3] for t in tri],[1,1,1.]])
    rhs=np.array([0.,0.,1.])
    try:w=np.linalg.solve(M,rhs)
    except:continue
    if np.all(w>=-1e-9):
     x=sum(w[k]*pts[t][0] for k,t in enumerate(tri));y=sum(w[k]*pts[t][1] for k,t in enumerate(tri));
     # gradients solve affine p/q -> jac
     xy=np.array([[pts[t][0],pts[t][1],1] for t in tri])
     cp=np.linalg.solve(xy,np.array([pts[t][2] for t in tri]));cq=np.linalg.solve(xy,np.array([pts[t][3] for t in tri]));det=cp[0]*cq[1]-cp[1]*cq[0]
     roots.append((x,y,det))
 print(diag,len(roots),'wedge',sum(x[2]>0 for x in roots),'tri',sum(x[2]<0 for x in roots))
 print(roots[:10])
PY","workdir":"/workspace","yield_time_ms":30000,"max_output_tokens":4000});
text(r.output);

